public static int calculateTimeNeeded(int N) {
    if (N <= 1) {
        return 0; // No time needed for 0 or 1 person
    }
    if (N % 2 == 1) {
        // Odd number of people: every person except the middle one needs to swap
        return N - 1;
    }
    if (N % 4 == 0) {
        // Even and divisible by 4: can be done in half the number of people (one round of swaps)
        return N / 2;
    }
    // Even but not divisible by 4: each needed swap takes two minutes
    return N;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new java.util.ArrayList<>();
    if (nums == null) {
        return res;
    }
    int n = nums.length;
    int[] cur = java.util.Arrays.copyOf(nums, n);
    java.util.Arrays.sort(cur);
    while (true) {
        java.util.List<Integer> list = new java.util.ArrayList<>(n);
        for (int v : cur) {
            list.add(v);
        }
        res.add(list);
        int i = n - 2;
        while (i >= 0 && cur[i] >= cur[i + 1]) {
            i--;
        }
        if (i < 0) {
            break;
        }
        int j = n - 1;
        while (cur[j] <= cur[i]) {
            j--;
        }
        int temp = cur[i];
        cur[i] = cur[j];
        cur[j] = temp;
        int left = i + 1;
        int right = n - 1;
        while (left < right) {
            int t = cur[left];
            cur[left] = cur[right];
            cur[right] = t;
            left++;
            right--;
        }
    }
    return res;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    List<Integer> current = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    class Backtrack {
        void dfs() {
            if (current.size() == nums.length) {
                result.add(new ArrayList<>(current));
                return;
            }
            for (int i = 0; i < nums.length; i++) {
                if (used[i]) continue;
                used[i] = true;
                current.add(nums[i]);
                dfs();
                current.remove(current.size() - 1);
                used[i] = false;
            }
        }
    }
    new Backtrack().dfs();
    return result;
}

