public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String base = strings.get(0);
    if (base == null || base.isEmpty()) {
        return 0;
    }
    int baseLen = base.length();
    for (int len = baseLen; len >= 1; len--) {
        for (int start = 0; start <= baseLen - len; start++) {
            String candidate = base.substring(start, start + len);
            String reversed = new StringBuilder(candidate).reverse().toString();
            boolean allMatch = true;
            for (int i = 1; i < strings.size(); i++) {
                String s = strings.get(i);
                if (s == null) {
                    s = "";
                }
                if (!(s.contains(candidate) || s.contains(reversed))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

