                // Use iterative DFS with a stack
                int[] stackR = new int[rows * cols];
                int[] stackC = new int[rows * cols];
                int top = 0;
                stackR[top] = r;
                stackC[top] = c;
                top++;
                visited[r][c] = true;

                while (top > 0) {
                    top--;
                    int cr = stackR[top];
                    int cc = stackC[top];
                    for (int k = 0; k < 8; k++) {
