public static int countDoubles(int[] numbers) {
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 != 0) continue;           // Only even numbers can be twice another integer
        int half = num / 2;
        Integer freqHalf = freq.get(half);
        if (freqHalf == null) continue;       // No matching element found
        if (half == num) {
            if (freqHalf > 1) {               // Need at least two identical elements
                count++;
            }
        } else {
            count++;
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int s = start[0];
    int t = end[0];
    if (s == t) {
        return "can be travelled";
    }
    if (s < 0 || s >= n || t < 0 || t >= n) {
        return "cannot be travelled";
    }
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] p : paths) {
        if (p == null || p.length < 2) continue;
        int u = p[0];
        int v = p[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        adj[u].add(v);
        adj[v].add(u);
    }
    boolean[] visited = new boolean[n];
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(s);
    visited[s] = true;
    while (!stack.isEmpty()) {
        int cur = stack.pop();
        for (int nb : adj[cur]) {
            if (!visited[nb]) {
                if (nb == t) {
                    return "can be travelled";
                }
                visited[nb] = true;
                stack.push(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null
        || start.length < 2 || end.length < 2
        || start[0] < 0 || start[1] < 0 || start[0] >= n || start[1] >= n
        || end[0] < 0 || end[1] < 0 || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }
    int total = n * n;
    // Build adjacency list
    java.util.List< java.util.List<Integer> > adj = new java.util.ArrayList<>(total);
    for (int i = 0; i < total; i++) adj.add(new java.util.ArrayList<>());
    if (paths != null) {
        for (int[] edge : paths) {
            if (edge == null || edge.length < 2) continue;
            int u = edge[0];
            int v = edge[1];
            if (u >= 0 && u < total && v >= 0 && v < total) {
                adj.get(u).add(v);
                adj.get(v).add(u);
            }
        }
    }
    int startId = start[0] * n + start[1];
    int endId   = end[0] * n + end[1];
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    boolean[] visited = new boolean[total];
    queue.add(startId);
    visited[startId] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == endId) {
            return "can be travelled";
        }
        for (int nb : adj.get(cur)) {
            if (!visited[nb]) {
                visited[nb] = true;
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n
            || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }
    int maxIndex = n * n;
    int startId = start[0] * n + start[1];
    int endId = end[0] * n + end[1];
    if (startId == endId) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.List<Integer>[] adj = new java.util.ArrayList[maxIndex];
    for (int i = 0; i < maxIndex; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] p : paths) {
        if (p == null || p.length < 4) continue;
        int r1 = p[0], c1 = p[1], r2 = p[2], c2 = p[3];
        if (r1 < 0 || r1 >= n || c1 < 0 || c1 >= n
                || r2 < 0 || r2 >= n || c2 < 0 || c2 >= n) {
            continue;
        }
        int id1 = r1 * n + c1;
        int id2 = r2 * n + c2;
        adj[id1].add(id2);
        adj[id2].add(id1);
    }

    boolean[] visited = new boolean[maxIndex];
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    queue.offer(startId);
    visited[startId] = true;

    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == endId) {
            return "can be travelled";
        }
        for (int neigh : adj[cur]) {
            if (!visited[neigh]) {
                visited[neigh] = true;
                queue.offer(neigh);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    java.util.HashMap<String, java.util.List<String>> adj = new java.util.HashMap<>();
    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);
    adj.putIfAbsent(startKey, new java.util.ArrayList<>());
    adj.putIfAbsent(endKey, new java.util.ArrayList<>());
    for (int[] p : paths) {
        if (p == null || p.length < 4) {
            continue;
        }
        int[] a = new int[]{p[0], p[1]};
        int[] b = new int[]{p[2], p[3]};
        String keyA = java.util.Arrays.toString(a);
        String keyB = java.util.Arrays.toString(b);
        adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adj.getOrDefault(current, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int src = start[0];
    int dst = end[0];
    if (src < 0 || src >= n || dst < 0 || dst >= n) {
        return "cannot be travelled";
    }
    if (src == dst) {
        return "can be travelled";
    }
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] p : paths) {
        if (p == null || p.length < 2) {
            continue;
        }
        int a = p[0];
        int b = p[1];
        if (a >= 0 && a < n && b >= 0 && b < n) {
            adj[a].add(b);
            adj[b].add(a); // assuming undirected connection
        }
    }
    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    queue.add(src);
    visited[src] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int next : adj[cur]) {
            if (!visited[next]) {
                if (next == dst) {
                    return "can be travelled";
                }
                visited[next] = true;
                queue.add(next);
            }
        }
    }
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    // Count letters in each word
    int[] count1 = new int[256];
    int[] count2 = new int[256];
    for (char c : word1.toCharArray()) count1[c & 0xFF]++;
    for (char c : word2.toCharArray()) count2[c & 0xFF]++;
    // Compute common letter count (sum of minimum occurrences)
    int common = 0;
    for (int i = 0; i < 256; i++) {
        common += Math.min(count1[i], count2[i]);
    }
    int len1 = word1.length();
    int len2 = word2.length();
    int denom = len1 + len2;
    String value;
    if (common == 0) {
        value = "0";
    } else if (common == denom) {
        value = "1";
    } else {
        int gcd = gcd(common, denom);
        value = (common / gcd) + "/" + (denom / gcd);
    }
    return "appx(" + word1 + ", " + word2 + ") = " + value;
}

public static String convertDatesToWeekdays(String date) {
    try {
        // Split input date string by spaces
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid date format";
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        // Create a LocalDate instance
        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        // Get full month name
        String monthName = localDate.getMonth()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        // Get full weekday name
        String weekDay = localDate.getDayOfWeek()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        // Construct result string
        return monthName + " " + day + ", " + year + " is a " + weekDay;
    } catch (Exception e) {
        // Handle any parsing errors or invalid dates
        return "Invalid date format";
    }
}

