public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Date must be in format \"MM dd yyyy\"");
    }
    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Date contains non-numeric values", e);
    }
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Month out of range: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Day out of range: " + day);
    }
    String[] monthNames = {
        "January", "February", "March", "April",
        "May", "June", "July", "August",
        "September", "October", "November", "December"
    };
    String monthName = monthNames[month - 1];
    java.time.LocalDate localDate;
    try {
        localDate = java.time.LocalDate.of(year, month, day);
    } catch (java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date: " + date, e);
    }
    java.time.DayOfWeek dow = localDate.getDayOfWeek();
    String weekday = dow.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    return String.format("%s %d, %d is a %s", monthName, day, year, weekday);
}

