    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0L;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    int count = n - 2 * k;
    if (count <= 0) {
        return 0.0;
    }
    return (double) sum / count;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int toRemove = n / 20; // 5% of the elements
    java.util.Arrays.sort(arr);
    double sum = 0;
    int start = toRemove;
    int end = n - toRemove - 1;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }
    int remaining = n - 2 * toRemove;
    return sum / remaining;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int remove = n / 20; // 5% of elements
    if (remove == 0) {
        // If array too small to remove 5%, just compute mean of all elements
        long total = 0;
        for (int v : arr) {
            total += v;
        }
        return total / (double) n;
    }
    java.util.Arrays.sort(arr);
    long sum = 0L;
    for (int i = remove; i < n - remove; i++) {
        sum += arr[i];
    }
    return sum / (double) (n - 2 * remove);
}

public boolean canArrange(int[] arr, int k) {
    if (k == 0 || arr == null || arr.length % 2 != 0) {
        return false;
    }
    int n = arr.length;
    int[] freq = new int[Math.abs(k)];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) r += Math.abs(k);
        freq[r]++;
    }
    // check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= Math.abs(k) / 2; r++) {
        int complement = Math.abs(k) - r;
        if (r == complement) { // when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

