        graph[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    class DFS {
        int total = 0;
        boolean dfs(int node, int parent) {
            boolean has = hasApple[node];
            for (int nei : graph[node]) {
                if (nei == parent) continue;
                if (dfs(nei, node)) {
                    total += 2;
                    has = true;
                }
            }
            return has;
        }
    }
    DFS d = new DFS();
    d.dfs(0, -1);
    return d.total;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.List[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<Integer>();
    }
    for (int[] e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    int[] order = new int[n];
    java.util.Stack<Integer> stack = new java.util.Stack<Integer>();
    stack.push(0);
    parent[0] = -1;
    int idx = 0;
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int neigh : graph[node]) {
            if (neigh != parent[node]) {
                parent[neigh] = node;
                stack.push(neigh);
            }
        }
    }
    boolean[] has = hasApple.clone();
    int cost = 0;
    for (int i = n - 1; i > 0; i--) {
        int node = order[i];
        int p = parent[node];
        if (has[node]) {
            cost += 2;
            has[p] = true;
        }
    }
    return cost;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[256];
    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    StringBuilder result = new StringBuilder(s.length());
    int total = s.length();
    while (result.length() < total) {
        // Ascend from smallest to largest
        for (int i = 0; i < 256; i++) {
            if (freq[i] > 0) {
                result.append((char) i);
                freq[i]--;
            }
        }
        // Descend from largest to smallest
        for (int i = 255; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) i);
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }

    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    boolean ascending = true;

    while (remaining > 0) {
        if (ascending) {
            for (int i = 0; i < 26; i++) {
                while (freq[i] > 0) {
                    result.append((char) ('a' + i));
                    freq[i]--;
                    remaining--;
                }
            }
        } else {
            for (int i = 25; i >= 0; i--) {
                while (freq[i] > 0) {
                    result.append((char) ('a' + i));
                    freq[i]--;
                    remaining--;
                }
            }
        }
        ascending = !ascending;
    }

    return result.toString();
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder(s.length());
    int total = s.length();

    while (total > 0) {
        // Ascending part
        for (int i = 0; i < 26; i++) {
            if (freq[i] == 0) continue;
            result.append((char) ('a' + i));
            freq[i]--;
            total--;
            // Continue selecting the next larger character
            while (true) {
                int j = i + 1;
                while (j < 26 && freq[j] == 0) j++;
                if (j == 26) break;
                result.append((char) ('a' + j));
                freq[j]--;
                total--;
                i = j; // Update current index to the newly added character
            }
            break; // Ascending part completed for this round
        }
        if (total == 0) break;

        // Descending part
        for (int i = 25; i >= 0; i--) {
            if (freq[i] == 0) continue;
            result.append((char) ('a' + i));
            freq[i]--;
            total--;
            // Continue selecting the next smaller character
            while (true) {
                int j = i - 1;
                while (j >= 0 && freq[j] == 0) j--;
                if (j < 0) break;
                result.append((char) ('a' + j));
                freq[j]--;
                total--;
                i = j; // Update current index to the newly added character
            }
            break; // Descending part completed for this round
        }
    }

    return result.toString();
}

