}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.put(ch, freq.getOrDefault(ch, 0) + 1);
    }
    StringBuilder sb = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending phase
        Character cur = freq.firstKey();
        int cnt = freq.get(cur) - 1;
        if (cnt == 0) {
            freq.remove(cur);
        } else {
            freq.put(cur, cnt);
        }
        sb.append(cur);
        while (true) {
            Character next = freq.higherKey(cur);
            if (next == null) break;
            cnt = freq.get(next) - 1;
            if (cnt == 0) {
                freq.remove(next);
            } else {
                freq.put(next, cnt);
            }
            sb.append(next);
            cur = next;
        }
        if (freq.isEmpty()) {
            break;
        }
        // Descending phase
        Character last = freq.lastKey();
        cnt = freq.get(last) - 1;
        if (cnt == 0) {
            freq.remove(last);
        } else {
            freq.put(last, cnt);
        }
        sb.append(last);
        while (true) {
            Character prev = freq.lowerKey(last);
            if (prev == null) break;
            cnt = freq.get(prev) - 1;
            if (cnt == 0) {
                freq.remove(prev);
            } else {
                freq.put(prev, cnt);
            }
            sb.append(prev);
            last = prev;
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    // dp[k] will contain all possible sums of subsets of size k
    java.util.ArrayList<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<>());
    }
    dp.get(0).add(0);
    for (int num : nums) {
        for (int k = n; k >= 1; k--) {
            java.util.Set<Integer> prev = dp.get(k - 1);
            if (!prev.isEmpty()) {
                java.util.Set<Integer> curr = dp.get(k);
                for (int sum : prev) {
                    curr.add(sum + num);
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if (total % k == 0) {
            int target = total / k;
            if (dp.get(k).contains(target)) {
                return true;
            }
        }
    }
    return false;
}

