        // iterate sizes descending to avoid using the same element twice
        for (int size = n - 1; size >= 0; size--) {
            if (dp.get(size).isEmpty()) continue;
            for (int prevSum : dp.get(size)) {
                dp.get(size + 1).add(prevSum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        // Check if total*k is divisible by n
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (dp.get(k).contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return 0; // Can start at step 1 (outside the array) for free.
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dp[0] = dp[1] = 0, representing starting at step 0 or 1 without paying cost
    int prev1 = 0; // dp[i-1]
    int prev2 = 0; // dp[i-2]
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = cur;
    }
    // For n == 1, the loop is skipped and prev1 stays 0
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

