public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
    int n = s.length();
    if (n < k) return false;
    int totalCodes = 1 << k;
    if (totalCodes > (1 << 20)) { // fallback to HashSet for large k
        Set<String> seen = new HashSet<>();
        for (int i = 0; i + k <= n; i++) {
            seen.add(s.substring(i, i + k));
            if (seen.size() == totalCodes) return true;
        }
        return seen.size() == totalCodes;
    }
    boolean[] seen = new boolean[totalCodes];
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    seen[mask] = true;
    int count = 1;
    int maskLimit = totalCodes - 1;
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) | (s.charAt(i) - '0')) & maskLimit;
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
            if (count == totalCodes) return true;
        }
    }
    return count == totalCodes;
}

