public int minInsertions(String s) {
    // Handle null input gracefully by treating it as an empty string.
    if (s == null) {
        return 0;
    }

    int insertions = 0;
    int balance = 0; // number of unmatched '('

    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '(') {
            balance++;
        } else if (ch == ')') {
            if (balance > 0) {
                balance--; // match this ')' with an existing '('
            } else {
                insertions++; // need an additional '(' before this ')'
            }
        } else {
            // Unexpected character; ignore or could throw an exception.
            // Here we simply ignore it to maintain robustness.
        }
    }

    // Any remaining unmatched '(' require ')' insertions.
    insertions += balance;

    return insertions;
}

