public int minOperations(int n) {
    int m = n / 2;
    if (n % 2 == 0) {
        return m * m;
    } else {
        return m * (m + 1);
    }
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    long ops = 0;
    int start = n / 2;
    for (int i = start; i < n; i++) {
        int current = 2 * i + 1;
        int diff = current - n;
        if (diff > 0) {
            ops += diff;
        }
    }
    return (int) ops;
}

