    for (int i = 1; i < nums.length; i++) {
        long val = nums[i];
        curMax = Math.max(val, curMax + val);
        curMin = Math.min(val, curMin + val);
        if (curMax > globalMax) {
            globalMax = curMax;
        }
        if (curMin < globalMin) {
            globalMin = curMin;
        }
    }
    long result = Math.max(globalMax, -globalMin);
