            small.add(i);
            int complement = n / i;
            if (complement != i) {
                large.add(complement);
            }
        }
    }
    int count = 0;
    for (int f : small) {
        count++;
        if (count == k) {
            return f;
        }
    }
    java.util.Collections.reverse(large);
    for (int f : large) {
        count++;
        if (count == k) {
            return f;
        }
    }
    return -1;
}

