public int kthFactor(int n, int k) {
    // Store small factors in ascending order and large factors in descending order
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();

    for (int i = 1; i <= n / i; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart); // large factors are added in descending order
            }
        }
    }

    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }

    if (k <= small.size()) {
        return small.get(k - 1);
    }

    // For remaining factors, we need to pick from large in ascending order.
    // Since large is in descending order, its ascending order is reversed.
    int indexInLargeAsc = k - small.size() - 1;
    int indexInLargeDesc = large.size() - 1 - indexInLargeAsc;
    return large.get(indexInLargeDesc);
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    // large is in decreasing order; reverse to ascending
    java.util.Collections.reverse(large);
    int count = 0;
    for (int f : small) {
        count++;
        if (count == k) return f;
    }
    for (int f : large) {
        count++;
        if (count == k) return f;
    }
    return -1;
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0 && Math.abs(stack.charAt(len - 1) - c) == 32) {
            stack.deleteCharAt(len - 1);
        } else {
            stack.append(c);
        }
    }
    return stack.toString();
}

