        char c = s.charAt(i);
        int len = sb.length();
        if (len > 0) {
            char prev = sb.charAt(len - 1);
            if (Math.abs(c - prev) == 32) { // opposite case of the same letter
                sb.setLength(len - 1);
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

