public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] result = {0};

    class Solver {
        void dfs(int pos, Set<String> used) {
            if (pos == n) {
                result[0] = Math.max(result[0], used.size());
                return;
            }
            for (int i = pos + 1; i <= n; i++) {
                String sub = s.substring(pos, i);
                if (!used.contains(sub)) {
                    used.add(sub);
                    dfs(i, used);
                    used.remove(sub);
                }
            }
        }
    }

    new Solver().dfs(0, new HashSet<>());
    return result[0];
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    final int n = s.length();
    final int[] best = {0};
    java.util.Set<String> used = new java.util.HashSet<>();

    java.util.function.Consumer<Integer> dfs = new java.util.function.Consumer<Integer>() {
        @Override
        public void accept(Integer idx) {
            if (idx == n) {
                best[0] = Math.max(best[0], used.size());
                return;
            }
            for (int end = idx + 1; end <= n; end++) {
                String sub = s.substring(idx, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    accept(end);
                    used.remove(sub);
                }
            }
        }
    };
    dfs.accept(0);
    return best[0];
}

