public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if ("../".equals(log)) {
            if (depth > 0) {
                depth--;
            }
        } else if ("./".equals(log)) {
            // do nothing
        } else {
            // any other entry is a folder creation and move into it
            depth++;
        }
    }
    return depth;
}

public int minOperations(String[] logs) {
    // Handle null or empty input gracefully
    if (logs == null || logs.length == 0) {
        return 0;
    }

    int depth = 0;

    for (String log : logs) {
        if (log == null || log.isEmpty()) {
            // Ignore malformed or empty entries
            continue;
        }

        try {
            if (log.equals("./")) {
                // Stay in the current directory; no change to depth
            } else if (log.equals("../")) {
                // Move to the parent directory if possible
                if (depth > 0) {
                    depth--;
                }
            } else if (log.endsWith("/") && !log.equals("../") && !log.equals("./")) {
                // Any other string ending with '/' is treated as navigating into a subdirectory
                depth++;
            } else {
                // Any other malformed operation is ignored
            }
        } catch (Exception e) {
            // If any unexpected exception occurs while processing a log,
            // continue with the next log entry.
            // In a real-world scenario you might log this exception.
            continue;
        }
    }

    // The minimal number of steps required to return to the main folder
    // is equal to the current depth
    return depth;
}

