public String getSmallestString(int n, int k) {
    if (n <= 0 || k < n || k > 26L * n) {
        throw new IllegalArgumentException("Invalid n or k");
    }
    char[] chars = new char[n];
    java.util.Arrays.fill(chars, 'a');
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int inc = Math.min(remaining, 25);
        chars[i] = (char) ('a' + inc);
        remaining -= inc;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    if (k < n || k > 26L * n) {
        throw new IllegalArgumentException("k is out of valid range for given n");
    }
    StringBuilder sb = new StringBuilder(n);
    int remainingSum = k;
    for (int i = 0; i < n; i++) {
        int remainingPos = n - i - 1;
        int minVal = 1;
        int maxPossibleForRemaining = remainingPos * 26;
        int chosen = Math.max(minVal, remainingSum - maxPossibleForRemaining);
        if (chosen > 26) {
            chosen = 26;
        }
        sb.append((char) ('a' + chosen - 1));
        remainingSum -= chosen;
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k must be between n and 26*n inclusive");
    }

    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a'); // start with all 'a's, value = n
    int remaining = k - n; // the extra value we need to distribute

    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase up to 25 ('z' - 'a')
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int maxVal = 26 * n;
    if (k < n || k > maxVal) {
        throw new IllegalArgumentException("k must be between " + n + " and " + maxVal);
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int inc = Math.min(25, remaining);
        sb.setCharAt(i, (char) ('a' + inc));
        remaining -= inc;
    }
    return sb.toString();
}

