public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        // Update 'ones' to have bits that have appeared once (mod 3)
        ones = (ones ^ num) & ~twos;
        // Update 'twos' to have bits that have appeared twice (mod 3)
        twos = (twos ^ num) & ~ones;
    }
    // When the loop ends, 'ones' contains the bits of the unique number
    return ones;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int bit = 0; bit < 32; bit++) {
        int sum = 0;
        for (int num : nums) {
            if (((num >> bit) & 1) == 1) {
                sum++;
            }
        }
        if ((sum % 3) != 0) {
            result |= (1 << bit);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int[] bitCounts = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            if (((num >> i) & 1) != 0) {
                bitCounts[i]++;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCounts[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int ones = 0;   // bits appeared once
    int twos = 0;   // bits appeared twice
    for (int num : nums) {
        // Bits which have appeared twice
        int newTwos = twos | (ones & num);
        // Bits which have appeared once
        int newOnes = ones ^ num;
        // Bits which have appeared three times
        int common = newOnes & newTwos;
        // Remove bits that have appeared three times
        ones = newOnes & ~common;
        twos = newTwos & ~common;
    }
    return ones;
}

