    for (int i = 0; i < 32; i++) {
        if ((bitCnt[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // zero is a stepping number
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    for (int i = 1; i <= 9; i++) {
        Queue<Long> queue = new LinkedList<>();
        queue.offer((long) i);
        while (!queue.isEmpty()) {
            long curr = queue.poll();
            if (curr > high) {
                continue;
            }
            if (curr >= low) {
                result.add((int) curr);
            }
            if (curr <= high / 10) {
                int lastDigit = (int) (curr % 10);
                if (lastDigit > 0) {
                    long next = curr * 10 + (lastDigit - 1);
                    queue.offer(next);
                }
                if (lastDigit < 9) {
                    long next = curr * 10 + (lastDigit + 1);
                    queue.offer(next);
                }
            }
        }
    }
    Collections.sort(result);
    return result;
}

