public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long result = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (current == 0) {
            result += higher * factor;
        } else if (current == 1) {
            result += higher * factor + lower + 1;
        } else {
            result += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long count = 0;
    for (long i = 1; i <= n; i *= 10) {
        long high = n / (i * 10);
        int cur = (int) ((n / i) % 10);
        long low = n % i;
        if (cur == 0) {
            count += high * i;
        } else if (cur == 1) {
            count += high * i + low + 1;
        } else {
            count += (high + 1) * i;
        }
    }
    return (int) count;
}

