    }
    long count = 0;
    long factor = 1;
    long num = n;
    while (factor <= num) {
        long nextFactor = factor * 10L;
        long right = num % factor;
        long current = (num / factor) % 10L;
        long left = num / nextFactor;
        count += left * factor;
        if (current == 1L) {
            count += right + 1;
        } else if (current > 1L) {
            count += factor;
        }
        factor = nextFactor;
    }
    return (int) count;
}

