public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    // Handle case where rows might have different lengths
    for (int[] row : mat) {
        if (row == null || row.length != n) {
            throw new IllegalArgumentException("All rows must have the same number of columns");
        }
    }

    int[][] horizontal = new int[m][n];
    int[][] vertical   = new int[m][n];
    int[][] diagonal   = new int[m][n]; // top-left to bottom-right (\)
    int[][] antiDiag   = new int[m][n]; // top-right to bottom-left (/)

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                vertical[i][j]   = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                diagonal[i][j]   = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                antiDiag[i][j]   = (i > 0 && j < n - 1 ? antiDiag[i - 1][j + 1] : 0) + 1;

                int cellMax = Math.max(
                        Math.max(horizontal[i][j], vertical[i][j]),
                        Math.max(diagonal[i][j], antiDiag[i][j]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j]   = 0;
                diagonal[i][j]   = 0;
                antiDiag[i][j]   = 0;
            }
        }
    }

    return maxLen;
}

