    }
    int m = mat.length;
    int n = mat[0].length;
    int[][][] dp = new int[m][n][4];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;           // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;           // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1; // main diagonal
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1; // anti-diagonal
                for (int d = 0; d < 4; d++) {
                    if (dp[i][j][d] > maxLen) {
                        maxLen = dp[i][j][d];
                    }
                }
            }
        }
    }
    return maxLen;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    // DP arrays to hold lengths in four directions
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] antiDiag = new int[m][n];
    int maxLen = 0;

    try {
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] != 1) {
                    // Reset counts for 0s
                    horiz[i][j] = 0;
                    vert[i][j] = 0;
                    diag[i][j] = 0;
                    antiDiag[i][j] = 0;
                    continue;
                }
                // Horizontal
                horiz[i][j] = 1 + (j > 0 ? horiz[i][j - 1] : 0);
                // Vertical
                vert[i][j] = 1 + (i > 0 ? vert[i - 1][j] : 0);
                // Diagonal (\)
                diag[i][j] = 1 + (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0);
                // Anti-diagonal (/)
                antiDiag[i][j] = 1 + (i > 0 && j < n - 1 ? antiDiag[i - 1][j + 1] : 0);

                // Update maximum
                int currentMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                          Math.max(diag[i][j], antiDiag[i][j]));
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            }
        }
    } catch (Exception e) {
        // In case of unexpected runtime errors, log and return 0
        // Logging is omitted here for brevity
        return 0;
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long value = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (value > 0) {
        sb.append((char) ('0' + (int) (value % 10)));
        value /= 10;
        count++;
        if (value > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

