public static String addThousandSeparator(int n) {
    // Handle zero separately because abs(Integer.MIN_VALUE) would overflow
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Convert to long to avoid overflow when negating Integer.MIN_VALUE
    long value = n;
    if (value < 0) {
        value = -value;
    }

    String numStr = Long.toString(value);
    int length = numStr.length();

    // Determine the length of the first group (may be less than 3)
    int firstGroupLen = length % 3;
    if (firstGroupLen == 0) {
        firstGroupLen = 3;
    }

    StringBuilder sb = new StringBuilder();
    // Append the first group
    sb.append(numStr, 0, firstGroupLen);

    // Append remaining groups prefixed with a dot
    for (int i = firstGroupLen; i < length; i += 3) {
        sb.append('.');
        sb.append(numStr, i, i + 3);
    }

    // Prepend minus sign if original number was negative
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

