public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute perfect squares up to maximum possible sum
    int maxVal = 0;
    for (int val : A) if (val > maxVal) maxVal = val;
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; ; i++) {
        int sq = i * i;
        if (sq > maxSum) break;
        isSquare[sq] = true;
    }

    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1L;
    }

    for (int mask = 1; mask < (1 << n); mask++) {
        for (int last = 0; last < n; last++) {
            long curCount = dp[mask][last];
            if (curCount == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (isSquare[A[last] + A[next]]) {
                    dp[mask | (1 << next)][next] += curCount;
                }
            }
        }
    }

    long total = 0;
    int fullMask = (1 << n) - 1;
    for (int i = 0; i < n; i++) {
        total += dp[fullMask][i];
    }

    // Count duplicate values
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int val : A) freq.put(val, freq.getOrDefault(val, 0) + 1);
    long dupFactor = 1L;
    for (int count : freq.values()) {
        for (int i = 2; i <= count; i++) {
            dupFactor *= i;
        }
    }

    long uniquePermutations = total / dupFactor;
    return (int) uniquePermutations;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 1; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    boolean[][] canSum = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                canSum[i][j] = isSquare[A[i] + A[j]];
            }
        }
    }
    long[][] memo = new long[1 << n][n + 1];
    for (int i = 0; i < memo.length; i++) {
        java.util.Arrays.fill(memo[i], -1L);
    }
    long result = dfs(0, -1, n, memo, canSum, A);
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    int maxVal = A[n - 1];
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int s = 0; s * s <= maxSum; s++) {
        isSquare[s * s] = true;
    }

    // Memoization table: mask -> last index
    long[][] memo = new long[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(memo[i], -1L);
    }

    java.util.function.LongBinaryOperator dfs = new java.util.function.LongBinaryOperator() {
        @Override
        public long applyAsLong(long mask, long lastIndex) {
            int maskInt = (int) mask;
            int last = (int) lastIndex;
            if (maskInt == (1 << n) - 1) {
                return 1L;
            }
            long cached = memo[maskInt][last];
            if (cached != -1L) {
                return cached;
            }
            long res = 0L;
            for (int i = 0; i < n; i++) {
                if (((maskInt >> i) & 1) == 1) continue;
                if (!isSquare[A[i] + A[last]]) continue;
                if (i > 0 && A[i] == A[i - 1] && (((maskInt >> (i - 1)) & 1) == 0)) continue;
                res += applyAsLong(maskInt | (1 << i), i);
            }
            memo[maskInt][last] = res;
            return res;
        }
    };

    long total = 0L;
    for (int i = 0; i < n; i++) {
        if (i > 0 && A[i] == A[i - 1]) continue; // avoid duplicate starting positions
        total += applyAsLong((1 << i), i);
    }

    if (total > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }
    return (int) total;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    // Count frequency of each number
    Map<Integer, Integer> freqMap = new HashMap<>();
    int maxVal = 0;
    for (int num : A) {
        freqMap.merge(num, 1, Integer::sum);
        if (num > maxVal) {
            maxVal = num;
        }
    }
    // List of unique values
    int k = freqMap.size();
    int[] values = new int[k];
    int[] rem = new int[k];
    int idx = 0;
    for (Map.Entry<Integer, Integer> e : freqMap.entrySet()) {
        values[idx] = e.getKey();
        rem[idx] = e.getValue();
        idx++;
    }
    // Precompute perfect squares up to 2*maxVal
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int s = 0; s * s <= maxSum; s++) {
        isSquare[s * s] = true;
    }

    // Memoization map: key -> count of permutations
    Map<String, Integer> memo = new HashMap<>();

    // Recursive DFS helper
    class Solver {
        int dfs(int lastIdx, int[] remaining) {
            boolean allZero = true;
            for (int c : remaining) {
                if (c > 0) {
                    allZero = false;
                    break;
                }
            }
            if (allZero) {
                return 1;
            }
            StringBuilder keyBuilder = new StringBuilder();
            keyBuilder.append(lastIdx).append('|');
            for (int c : remaining) {
                keyBuilder.append(c).append(',');
            }
            String key = keyBuilder.toString();
            if (memo.containsKey(key)) {
                return memo.get(key);
            }
            int count = 0;
            for (int i = 0; i < k; i++) {
                if (remaining[i] == 0) {
                    continue;
                }
                if (lastIdx != -1 && !isSquare[values[lastIdx] + values[i]]) {
                    continue;
                }
                remaining[i]--;
                count += dfs(i, remaining);
                remaining[i]++;
            }
            memo.put(key, count);
            return count;
        }
    }

    Solver solver = new Solver();
    return solver.dfs(-1, rem);
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    int n = heights.length;
    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        if (curHeight < 0) {
            throw new IllegalArgumentException("heights array contains negative value at index " + i);
        }
        while (!stack.isEmpty() && curHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    // Defensive check: null or empty array
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int n = heights.length;
    // Use an array as a stack to hold indices of increasing bar heights
    int[] stack = new int[n + 1];
    int top = -1; // stack is empty when top == -1

    for (int i = 0; i <= n; i++) {
        // For the sentinel case at the end, treat height as 0
        int currentHeight = (i == n) ? 0 : heights[i];

        // While the current bar is smaller than the one at the stack's top,
        // calculate area with the bar at stack's top as the smallest bar.
        while (top != -1 && heights[stack[top]] > currentHeight) {
            int height = heights[stack[top--]]; // pop
            int width = (top == -1) ? i : (i - stack[top] - 1);
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        // Push current index onto stack
        stack[++top] = i;
    }

    return maxArea;
}

