public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] res = new int[total];
    int k = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.max(0, sum - n + 1);
        int endRow = Math.min(m - 1, sum);
        if (sum % 2 == 0) {
            for (int row = endRow; row >= startRow; row--) {
                int col = sum - row;
                if (col >= 0 && col < n) {
                    res[k++] = mat[row][col];
                }
            }
        } else {
            for (int row = startRow; row <= endRow; row++) {
                int col = sum - row;
                if (col >= 0 && col < n) {
                    res[k++] = mat[row][col];
                }
            }
        }
    }
    return res;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int index = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int rStart = Math.max(0, sum - n + 1);
        int rEnd   = Math.min(m - 1, sum);
        if ((sum & 1) == 0) { // even sum: traverse bottom-to-top
            for (int r = rEnd; r >= rStart; r--) {
                int c = sum - r;
                res[index++] = mat[r][c];
            }
        } else { // odd sum: traverse top-to-bottom
            for (int r = rStart; r <= rEnd; r++) {
                int c = sum - r;
                res[index++] = mat[r][c];
