}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int index = 0;
    for (int k = 0; k <= m + n - 2; k++) {
        int iStart = Math.max(0, k - n + 1);
        int iEnd = Math.min(m - 1, k);
        if (k % 2 == 0) { // even: reverse order
            for (int i = iEnd; i >= iStart; i--) {
                int j = k - i;
                res[index++] = mat[i][j];
            }
        } else { // odd: forward order
            for (int i = iStart; i <= iEnd; i++) {
                int j = k - i;
                res[index++] = mat[i][j];
            }
        }
    }
    return res;
}

public static int[] diagonalOrder(int[][] mat) {
