    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int d = 0; d <= (m + n - 2); d++) {
        int rowStart = Math.max(0, d - n + 1);
        int rowEnd = Math.min(m - 1, d);
        if ((d & 1) == 0) {
            // even diagonal - traverse from rowEnd down to rowStart
            for (int row = rowEnd; row >= rowStart; row--) {
                int col = d - row;
                result[idx++] = mat[row][col];
            }
        } else {
            // odd diagonal - traverse from rowStart up to rowEnd
            for (int row = rowStart; row <= rowEnd; row++) {
                int col = d - row;
                result[idx++] = mat[row][col];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    boolean reversed = true; // start with true to match the required ordering pattern
    for (int d = 0; d < m + n - 1; d++) {
        // Determine the starting point of the current diagonal
        int r = Math.max(0, d - n + 1);
        int c = Math.min(d, n - 1);
        // Collect elements of this diagonal
        java.util.ArrayList<Integer> temp = new java.util.ArrayList<>();
        while (r < m && c >= 0) {
            temp.add(mat[r][c]);
            r++;
            c--;
        }
        // Add elements to result in correct order
        if (reversed) {
            for (int i = temp.size() - 1; i >= 0; i--) {
                result[idx++] = temp.get(i);
            }
        } else {
            for (int i = 0; i < temp.size(); i++) {
                result[idx++] = temp.get(i);
            }
        }
        reversed = !reversed;
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    return Integer.parseInt(new String(digits));
}

