    }
    if (i < 0) {
        // No larger permutation exists
        return -1;
    }

    // Step 2: Find the largest index j > i such that digits[j] > digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the sub-array from i+1 to end
    int start = i + 1;
    int end = len - 1;
    while (start < end) {
        char mid = digits[start];
        digits[start] = digits[end];
        digits[end] = mid;
        start++;
        end--;
    }

    // Convert back to integer; if overflow, return -1
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

