public static int findSmallestInteger(int n) {
    // Convert integer to array of its digits
    char[] chars = String.valueOf(n).toCharArray();
    int len = chars.length;
    int[] digits = new int[len];
    for (int i = 0; i < len; i++) {
        digits[i] = chars[i] - '0';
    }

    // Find the pivot: the first index from the right where digits[i - 1] < digits[i]
    int pivot = -1;
    for (int i = len - 1; i > 0; i--) {
        if (digits[i - 1] < digits[i]) {
            pivot = i - 1;
            break;
        }
    }

    // If no pivot, the digits are in non-increasing order; no greater permutation exists
    if (pivot == -1) {
        return -1;
    }

    // Find the rightmost successor to the pivot in the suffix
    int successor = len - 1;
    while (digits[successor] <= digits[pivot]) {
        successor--;
    }

    // Swap pivot with successor
    int tmp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = tmp;

    // Reverse the suffix starting at pivot + 1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        tmp = digits[left];
        digits[left] = digits[right];
        digits[right] = tmp;
        left++;
        right--;
    }

    // Construct the resulting integer
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
    }

    // Result is guaranteed to be greater than n, but check for overflow
    if (result > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) result;
}

