public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    // Pairs of digits that look like each other when rotated 180 degrees
    char[][] pairs = { { '0', '0' }, { '1', '1' }, { '6', '9' }, { '8', '8' }, { '9', '6' } };

    // Allowed middle digits for odd lengths
    char[] middle = { '0', '1', '8' };

    char[] num = new char[n];
    int leftLimit = n / 2;

    // Recursive helper to build the number
    java.util.function.Consumer<Integer> backtrack = new java.util.function.Consumer<Integer>() {
        @Override
        public void accept(Integer pos) {
            if (pos == leftLimit) {
                if (n % 2 == 0) {
                    result.add(new String(num));
                } else {
                    for (char m : middle) {
                        num[leftLimit] = m;
                        result.add(new String(num));
                    }
                }
                return;
            }
            for (char[] pair : pairs) {
                if (pos == 0 && pair[0] == '0' && n > 1) {
                    continue; // avoid leading zero for numbers longer than 1 digit
                }
                num[pos] = pair[0];
                num[n - 1 - pos] = pair[1];
                accept(pos + 1);
            }
        }
    };

    backtrack.accept(0);
    return result;
}

public static java.util.List<java.lang.String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new java.util.ArrayList<>();
    }
    class Solver {
        java.util.List<java.lang.String> solve(int len, int total) {
            if (len == 0) {
                java.util.List<java.lang.String> base = new java.util.ArrayList<>(1);
                base.add("");
                return base;
            }
            if (len == 1) {
                java.util.List<java.lang.String> base = new java.util.ArrayList<>(3);
                base.add("0");
                base.add("1");
                base.add("8");
                return base;
            }
            java.util.List<java.lang.String> sub = solve(len - 2, total);
            java.util.List<java.lang.String> res = new java.util.ArrayList<>(sub.size() * 5);
            for (java.lang.String s : sub) {
                if (len < total) {
                    res.add("0" + s + "0");
                }
                res.add("1" + s + "1");
                res.add("6" + s + "9");
                res.add("8" + s + "8");
                res.add("9" + s + "6");
            }
            return res;
        }
    }
    return new Solver().solve(n, n);
}

