public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>(n);
    if (n <= 0) {
        return res;
    }
    int cur = 1;
    for (int i = 0; i < n; i++) {
        res.add(cur);
        if (cur <= n / 10) {
            cur *= 10;
        } else {
            if (cur % 10 != 9 && cur < n) {
                cur++;
            } else {
                while (cur % 10 == 9 || cur == n) {
                    cur /= 10;
                    if (cur == 0) {
                        break;
                    }
                }
                cur++;
            }
        }
    }
    return res;
}

public static java.util.List<Integer> lexicalOrder(int n) {
    if (n <= 0) {
        return new java.util.ArrayList<>();
    }
    java.util.List<Integer> res = new java.util.ArrayList<>(n);
    int cur = 1;
    for (int i = 0; i < n; i++) {
        res.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            if (cur % 10 != 9 && cur + 1 <= n) {
                cur++;
            } else {
                while ((cur / 10) % 10 == 9) {
                    cur /= 10;
                }
                cur = cur / 10 + 1;
            }
        }
    }
    return res;
}

