}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    if (n <= 0) {
        return result;
    }
    int curr = 1;
    for (int i = 0; i < n; i++) {
        result.add(curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else {
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int cur = 1;
    while (result.size() < n) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur++;
        } else {
            cur /= 10;
            while (cur % 10 == 9 && cur > 0) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : nums) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

